//! Live2D 模型文件识别。

use std::path::Path;

/// 判断一个 JSON 是否是 Cubism 3/4/5 的 model3（或重命名后的 model.json）。
///
/// 只读取 `FileReferences.Moc`，不解析完整模型。
pub(crate) fn is_moc3(path: &Path) -> bool {
    if path
        .file_name()
        .and_then(|name| name.to_str())
        .is_some_and(|name| name.to_ascii_lowercase().ends_with(".model3.json"))
    {
        return true;
    }
    let Ok(text) = std::fs::read_to_string(path) else {
        return false;
    };
    let Ok(value) = serde_json::from_str::<serde_json::Value>(&text) else {
        return false;
    };
    value
        .get("FileReferences")
        .and_then(|references| references.get("Moc"))
        .and_then(|moc| moc.as_str())
        .is_some()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn distinguishes_cubism2_from_moc3() {
        let path = std::env::temp_dir().join("webgal-live2d-moc-detection.json");
        std::fs::write(&path, r#"{"model":".chara/model.moc"}"#).expect("write");
        assert!(!is_moc3(&path));
        std::fs::write(&path, r#"{"FileReferences":{"Moc":"model.moc3"}}"#).expect("write");
        assert!(is_moc3(&path));
        let _ = std::fs::remove_file(path);
    }
}
